import{b as e,O as t,g as l,j as c}from"./chunks/framework.DcaUmd3X.js";const i=JSON.parse('{"title":"也许你该找个人聊聊","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/maybe-talk/index.md","filePath":"读书感悟/电子书架/42.也许你该找个人聊聊.md","lastUpdated":1781614933000}'),p={name:"reading/digital/maybe-talk/index.md"};function u(b,o,k,q,a,r){return t(),l("div",null,[...o[0]||(o[0]=[c('<h1 id="也许你该找个人聊聊" tabindex="-1">也许你该找个人聊聊 <a class="header-anchor" href="#也许你该找个人聊聊" aria-label="Permalink to &quot;也许你该找个人聊聊&quot;">​</a></h1><p><code>洛莉·戈特利布</code> <code>心理学应用</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 “要心怀慈悲。”</p></blockquote><blockquote><p>📌 诚实总是困难的，尤其在自己特别想做点什么的时候，承认自己的无能为力。</p></blockquote><blockquote><p>📌 这是一个常见的心理防御机制，它叫做“心理间隔化”。</p></blockquote><blockquote><p>📌 事实上我们不是要保持中立，而是要尽力去留意自己非常不中立的情感、偏见和见解（我们称之为“反移情”）</p></blockquote><blockquote><p>📌 心理治疗师从一开始就知道，他们见到的每个来访者都只是一张抓拍的快照，只记录了某个人的某一个瞬间。或许这张快照的拍摄角度不怎么令人满意，刚好捕捉到了你尴尬的表情，但一定也会有把你拍得容光焕发的照片，捕捉到你正在打开礼物时的表情，或是和爱人一起面带春风的样子。无论是好是坏，都只是那个瞬间的你，并不代表你的全部。</p></blockquote><blockquote><p>📌 感受是无论如何都会存在的，所以你还不如张开双臂欢迎它们，因为这些感受里可能藏着重要的线索。</p></blockquote><blockquote><p>📌 不要评判你的感受。留意它们。把它们当作你的地图。不要害怕真相。</p></blockquote><blockquote><p>📌 一个人之所以能成为一个独立的个体，是因为他有自己的个性、记忆、经历、喜恶、所爱与所失、知识和能力，而这一切的载体就是这个只有三磅重的器官。</p></blockquote><blockquote><p>📌 在记忆和期望的共同作用下，会造成治疗师对治疗抱有偏见（即先入为主的看法</p></blockquote><blockquote><p>📌 大多数值得做的事情都不简单。”</p></blockquote><blockquote><p>📌 操不完的心</p></blockquote><blockquote><p>📌 心理治疗师关注的不只是来访者所说的话，甚至不仅限于视觉上的线索：抖动的脚、面部轻微的抽搐、微颤的下唇、因愤怒而紧缩的双眼。除了我们听到的和看到的，有些听不见、看不到的东西也同样重要，那就是屋子里流动的能量，是</p></blockquote><blockquote><p>📌 两个人共处时气场的对流。当两个人不处在同一个物理空间时，也就失去了那个无法言喻的维度。</p></blockquote><blockquote><p>📌 人们谈论自杀，通常不是因为想要终结自己的生命，而是因为想要终结痛苦</p></blockquote><blockquote><p>📌 我们将自己的原生家庭内化，成为我们人际关系中不断重复的主旋律”</p></blockquote><blockquote><p>📌 投射作用是指来访者将自己的想法强加到他人的身上，而投射性认同是指来访者通过诱导，将想法导入别人的内</p></blockquote><blockquote><p>📌 我认为如果你能想清楚为什么这个抉择对你来说这么艰难，那你才更能从这个思考中获</p></blockquote><blockquote><p>📌 这种事，遇上了也没什么稀</p></blockquote><blockquote><p>📌 现代人总是觉得如果做事不够迅速，就会损失一些时间。但面对省下来的时间又不知该怎么办，只能打发了事</p></blockquote><blockquote><p>📌 回避就是以不面对的方式来面对问题</p></blockquote><blockquote><p>📌 这四个终极问题是：死亡、孤独、自由和无意</p></blockquote><blockquote><p>📌 我开始意识到，不确定性并不代表着丧失希望，而是意味着还存在可能性。</p></blockquote><blockquote><p>📌 他和玛戈曾经约定过，永远不要在孩子们的面前吵架，所以那个时候，他们也还是遵守了彼此的约定。</p></blockquote><blockquote><p>📌 不过有一个阶段性模型我倒是几乎在每次治疗的每一分钟里都铭记于心——那就是完成一次改变所需经历的各个阶段</p></blockquote><blockquote><p>📌 一个人可以被剥夺任何东西，除了这个人最后的自由——在既定的环境下选择自己抱持什么态度的自由。</p></blockquote><blockquote><p>📌 在刺激和回应之间还留有一些空间，这个空间允许我们以自己的意志去选择我们的回应方式。我们所作出的回应包含了我们的成长和自由。”</p></blockquote><blockquote><p>📌 婴儿期（希望）——信任/不信任• 幼儿期（意志）——自主独立/羞怯怀疑• 学龄前（目的）——主动/内疚• 学童期（能力）——勤奋/自卑• 青少年（忠诚）——同一性/角色混乱• 青年成人（爱）——亲密/孤独• 中年成人（关怀）——再生力/停滞• 老年成人（智慧）——自我实现/绝望</p></blockquote><blockquote><p>📌 如果我们不顾自己的感受，就像是行走在冰面上而不顾</p></blockquote><blockquote><p>📌 下的暗涌，我们将无法得到安宁和快乐。</p></blockquote><blockquote><p>📌 生活的本质是变化，而人类的本性是抗拒变化</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 遗憾是有的，人生海海没有遗憾的人生是不完整的</p><p>📌 如果我们把当下的时间花在修改过去和控制未来上，还是会怀着无尽的遗憾被困在原地。</p></blockquote><blockquote><p>💭 这是一个悲伤的故事</p><p>📌 好吧，大概是在二十年前，我刚开始行医的时候，我的来访者里有一个患抑郁症的年轻小伙子。我感觉我们的治疗正在取得进步，但后来治疗进程似乎就停滞了。我以为是他还没有准备好要迈出下一步，但事实上我那时太缺乏经验了，完全没有能力判断其中的原委。后来他就不在我这里治疗了，大概一年之后，我在我自己的治疗师那儿遇到了他。”</p></blockquote>',36)])])}const _=e(p,[["render",u]]);export{i as __pageData,_ as default};
